 "content": "from collections import Counter, deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            y0 = min(y for y,x in cells); y1 = max(y for y,x in cells)
            x0 = min(x for y,x in cells); x1 = max(x for y,x in cells)
            if y1-y0 < 2 or x1-x0 < 2:
                continue
            cellset = set(cells)
            border = {(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1)
                      if y in (y0,y1) or x in (x0,x1)}
            if cellset != border:
                continue
            iy, ix = y1-y0-1, x1-x0-1
            fill = 7 if iy % 2 == 1 and ix % 2 == 1 else 2
            for y in range(y0+1,y1):
                for x in range(x0+1,x1):
                    g[y][x] = fill
    return g
